{
  "schema_version": 1,
  "observations": [
    {
      "key": "obs_01",
      "facet": "mechanism",
      "statement": "Binary search searches a sorted array by repeatedly dividing the search interval in half, starting with the whole array, narrowing to the lower half if the search key is less than the middle item, or the upper half otherwise, until the value is found or the interval is empty.",
      "start_line": 5,
      "end_line": 9
    },
    {
      "key": "obs_02",
      "facet": "term",
      "statement": "Binary search is a generalization of dichotomic search and a type of search.",
      "start_line": 10,
      "end_line": 15
    },
    {
      "key": "obs_03",
      "facet": "relation",
      "statement": "Binary search is used in or is a part of binary insertion sort, ideal merge, suffix array, and inversion list.",
      "start_line": 16,
      "end_line": 25
    },
    {
      "key": "obs_04",
      "facet": "relation",
      "statement": "Binary search is a part of or used in divide and conquer.",
      "start_line": 26,
      "end_line": 29
    },
    {
      "key": "obs_05",
      "facet": "property",
      "statement": "The run time of binary search is O(ln n).",
      "start_line": 39,
      "end_line": 42
    },
    {
      "key": "obs_06",
      "facet": "mechanism",
      "statement": "Finding the middle index is often coded as mid = (high + low)/2, but this overflows if high and low are close to the largest expressible integer; the overflow-safe alternative is mid = low + (high - low)/2 for non-negative high and low.",
      "start_line": 43,
      "end_line": 46
    },
    {
      "key": "obs_07",
      "facet": "property",
      "statement": "Binary search may be effective with an ordered linked list, making O(n) traversals (same as linear search) but performing only O(log n) comparisons.",
      "start_line": 48,
      "end_line": 52
    },
    {
      "key": "obs_08",
      "facet": "reference",
      "statement": "The entry is from the Dictionary of Algorithms and Data Structures, edited by Paul E. Black, modified 21 April 2022, available at https://www.nist.gov/dads/HTML/binarySearch.html.",
      "start_line": 80,
      "end_line": 85
    }
  ],
  "claims": [],
  "questions": []
}
